<template><div><div v-if="selected" class="source-card"><strong>{{ selected.goods_name || selected.sku_sn }}</strong><div>{{ selected.sku_sn }} · 本次申请 {{ quantity }} 件</div><div class="muted">{{ selected.exchange_sn ? '来自换货单 ' + selected.exchange_sn : '原销售发货' }}</div><div class="muted">{{ selected.shipment_sn }} · 发货明细 #{{ selected.source_shipment_line_id }} · 批次 {{ selected.batch_id }}</div><div v-if="disabled && appliedQuantity">已出库 {{ selected.shipped_quantity }} · 本次已申请 {{ appliedQuantity }} · 剩余可再申请 {{ Math.max(0, Number(selected.claimable_quantity) - appliedQuantity) }} 件</div><div v-else>已出库 {{ selected.shipped_quantity }} · 其他申请已占 {{ Math.max(0, Number(selected.shipped_quantity) - Number(selected.claimable_quantity)) }} · 本次可申请 {{ selected.claimable_quantity }} 件</div><el-button v-if="!disabled" size="small" @click="visible = true">更换实际来源</el-button></div><el-button v-else :disabled="disabled" @click="visible = true">选择实际发货来源</el-button><el-dialog title="选择本次实际退回来源" :visible.sync="visible" width="min(1200px, 96vw)" append-to-body :close-on-click-modal="false"><el-alert :closable="false" type="info" title="同一 SKU 不同次发货独立计算可申请量。A→B→A 时，请选择对应实际发货，不能复用最初 A 的额度。" /><el-table :data="sources" row-key="source_shipment_line_id"><el-table-column label="商品 / SKU" min-width="190"><template slot-scope="s">{{ s.row.goods_name }}<div class="muted">{{ s.row.sku_sn }}</div></template></el-table-column><el-table-column label="来源单据" min-width="280"><template slot-scope="s">{{ s.row.exchange_sn || '原销售发货' }}<div class="muted">{{ s.row.shipment_sn }}</div><div class="muted">明细 #{{ s.row.source_shipment_line_id }} · 批次 {{ s.row.batch_id }} · {{ s.row.store_code }}</div><div class="muted">{{ s.row.create_time }}</div></template></el-table-column><el-table-column label="已出库" prop="shipped_quantity" width="85" /><el-table-column label="其他申请已占" width="115"><template slot-scope="s">{{ Math.max(0, Number(s.row.shipped_quantity) - Number(s.row.claimable_quantity)) }}</template></el-table-column><el-table-column label="本次可申请" prop="claimable_quantity" width="110" /><el-table-column label="操作" width="110"><template slot-scope="s"><el-button type="text" :disabled="Number(s.row.claimable_quantity) < quantity" @click="$emit('input', s.row.source_shipment_line_id); visible = false">{{ Number(s.row.claimable_quantity) < quantity ? '数量不足' : '选择此来源' }}</el-button></template></el-table-column></el-table><span slot="footer"><el-button @click="visible = false">关闭</el-button></span></el-dialog></div></template>
<script>export default { props: { value: [Number, String], sources: { type: Array, default: () => [] }, quantity: Number, disabled: Boolean, appliedQuantity: { type: Number, default: 0 } }, data() { return { visible: false } }, computed: { selected() { return this.sources.find(s => String(s.source_shipment_line_id) === String(this.value)) } } }</script>
<style scoped>.source-card{border:1px solid #e1e8f1;border-radius:8px;padding:14px;line-height:1.9;background:#fff;overflow-wrap:anywhere}.muted{font-size:12px;color:#7b8798;line-height:1.7}.el-table{margin-top:16px}</style>
